#include<bits/stdc++.h>
using namespace std;

int digitsum(int x){
  string s=to_string(x);
  int ans=0;
  for(char c:s)ans+=c-'0';
  return ans;
}

int main(){
  int n,k;
  cin >> n >> k;

  int ans=0;
  for(int i=1;i<=n;i++)if(digitsum(i)==k)ans++;

  cout << ans << endl;
}

def digitsum(x):
  s=str(x)
  ans=0
  for c in s:
    ans+=int(c)
  return ans

n,k=map(int,input().split())
ans=0
for i in range(1,n+1):
  if digitsum(i)==k:
    ans+=1

print(ans)
